$logPath = 'C:\Windows\Setup\Scripts\InstallCloudbaseInit.log'; function Write-Log( [string] $msg ) { $ts = [datetime]::Now.ToString( 'yyyy-MM-dd HH:mm:ss' ); Add-Content -LiteralPath $logPath -Value ( $ts + ' ' + $msg ); }; Write-Log 'InstallCloudbaseInit starting.'; $msi = $null; foreach( $letter in 'DEFGHIJKLMNOPQRSTUVWXYZ'.ToCharArray() ) { foreach( $name in @( 'CloudbaseInitSetup_x64.msi'; 'CloudbaseInitSetup_1_1_8_x64.msi'; ) ) { $cand = $letter + ':\' + $name; if( Test-Path -LiteralPath $cand ) { $msi = $cand; break; } }; if( $msi ) { break; } }; $svc = Get-Service -Name 'cloudbase-init' -ErrorAction 'SilentlyContinue'; if( -not $svc ) { if( -not $msi ) { Write-Log 'ERROR: cloudbase-init service not present and no installer MSI found on install media. Skipping.'; return; }; Write-Log ( 'Installing ' + $msi ); $msiLog = 'C:\Windows\Temp\CloudbaseInitInstall.log'; $msiArgs = '/i "' + $msi + '" /qn /norestart /l*v "' + $msiLog + '" RUNSERVICEASLOCALSYSTEM=1'; $p = Start-Process -FilePath 'msiexec.exe' -ArgumentList $msiArgs -Wait -PassThru; Write-Log ( 'msiexec exit code: ' + $p.ExitCode ); if( ( $p.ExitCode -ne 0 ) -and ( $p.ExitCode -ne 3010 ) ) { Write-Log 'ERROR: msiexec failed. See msiexec log.'; return; }; } else { Write-Log 'cloudbase-init service already installed. Ensuring configuration.'; }; $confDir = 'C:\Program Files\Cloudbase Solutions\Cloudbase-Init\conf'; $srcDir = 'C:\Windows\Setup\Scripts'; foreach( $name in @( 'cloudbase-init.conf'; 'cloudbase-init-unattend.conf'; ) ) { $src = Join-Path $srcDir $name; $dst = Join-Path $confDir $name; if( Test-Path -LiteralPath $src ) { Copy-Item -LiteralPath $src -Destination $dst -Force; Write-Log ( 'Applied config ' + $dst ); } else { Write-Log ( 'WARNING: staged config missing: ' + $src ); } }; try { & sc.exe config cloudbase-init start= auto | Out-String | ForEach-Object { Write-Log $_; }; Set-Service -Name 'cloudbase-init' -StartupType 'Automatic' -ErrorAction 'Stop'; Write-Log 'cloudbase-init service is enabled (StartupType Automatic) and will run on next boot.'; } catch { Write-Log ( 'WARNING: could not set service startup type: ' + $_.Exception.Message ); }; Write-Log 'InstallCloudbaseInit finished.';
